package shop;

import static readcode.Assert.*;

import java.time.Duration;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;

public class ProductPageServiceTest {
    private static final Backends.Product LAMP = new Backends.Product("p1", "Desk lamp", 4500);

    private ProductPageService service(
            Backends.Products products, Backends.Recommendations recs, Backends.Reviews reviews) {
        return new ProductPageService(products, recs, reviews, Duration.ofMillis(100));
    }

    private static <T> CompletableFuture<T> failed(String message) {
        return CompletableFuture.failedFuture(new IllegalStateException(message));
    }

    private static <T> CompletableFuture<T> hangs() {
        return new CompletableFuture<>();
    }

    public void testHealthyPageHasEverything() {
        ProductPage page = service(
                id -> CompletableFuture.completedFuture(LAMP),
                id -> CompletableFuture.completedFuture(List.of("p2", "p3")),
                id -> CompletableFuture.completedFuture(List.of(new Backends.Review("sam", 5))))
                .load("p1");
        assertEquals(LAMP, page.product());
        assertEquals(List.of("p2", "p3"), page.recommendations());
        assertEquals(1, page.reviews().size());
        assertFalse(page.isDegraded());
    }

    public void testRecommendationErrorFallsBackToEmpty() {
        ProductPage page = service(
                id -> CompletableFuture.completedFuture(LAMP),
                id -> failed("recs 500"),
                id -> CompletableFuture.completedFuture(List.of()))
                .load("p1");
        assertEquals(List.of(), page.recommendations());
        assertEquals(List.of("recommendations"), page.degradedSections());
    }

    public void testHangingRecommendationsFallBackAfterTimeout() {
        ProductPage page = service(
                id -> CompletableFuture.completedFuture(LAMP),
                id -> hangs(),
                id -> CompletableFuture.completedFuture(List.of()))
                .load("p1");
        System.out.println("degraded sections: " + page.degradedSections());
        assertEquals(LAMP, page.product());
        assertEquals(List.of(), page.recommendations());
        assertTrue(page.isDegraded(), "a timed-out widget must be reported as degraded");
    }

    public void testHangingReviewsFallBackAfterTimeout() {
        ProductPage page = service(
                id -> CompletableFuture.completedFuture(LAMP),
                id -> CompletableFuture.completedFuture(List.of("p2")),
                id -> hangs())
                .load("p1");
        assertEquals(List.of(), page.reviews());
        assertEquals(List.of("p2"), page.recommendations());
        assertEquals(List.of("reviews"), page.degradedSections());
    }

    public void testBothWidgetsDownStillServesProduct() {
        ProductPage page = service(
                id -> CompletableFuture.completedFuture(LAMP),
                id -> hangs(),
                id -> failed("reviews 503"))
                .load("p1");
        assertEquals(LAMP, page.product());
        assertEquals(2, page.degradedSections().size());
    }

    public void testProductFailureIsNotHidden() {
        ProductPageService svc = service(
                id -> failed("catalog down"),
                id -> CompletableFuture.completedFuture(List.of()),
                id -> CompletableFuture.completedFuture(List.of()));
        assertThrows(CompletionException.class, () -> svc.load("p1"));
    }

    public void testSlowButInTimeWidgetIsKept() {
        CompletableFuture<List<String>> late = new CompletableFuture<>();
        ProductPageService svc = service(
                id -> CompletableFuture.completedFuture(LAMP),
                id -> late,
                id -> CompletableFuture.completedFuture(List.of()));
        late.complete(List.of("p9"));
        assertEquals(List.of("p9"), svc.load("p1").recommendations());
    }
}
